// Runs only after Slack confirms a message was sent.
// Produces the alert log row and the payload that saves the alert state, so a
// failed send never records state and never suppresses that deal in future runs.
//
// Slack returns its own API response rather than the deal, so the deal is found
// through n8n item linking. If that link cannot be made we stop rather than guess:
// not recording state is the safe direction.
const CHANNEL_BY_NODE = {
  'Send Critical Risk Alert': '#revops-risk',
  'Send High Risk Alert': '#revops-risk',
  'Send Routing Exception Alert': '#workflow-error'
};

let deal;
try {
  deal = $('Attach Recommended Action').item.json;
} catch (e) {
  throw new Error('Delivered Slack alert could not be traced back to its deal. Alert state was NOT recorded; this deal will re-alert on the next run.');
}

const dealId = String(deal && deal.dealId ? deal.dealId : '').trim();
if (!dealId) {
  throw new Error('Delivered Slack alert resolved to a record with no dealId. Alert state was NOT recorded.');
}

let sourceNode = '';
try {
  if (typeof $prevNode !== 'undefined' && $prevNode && $prevNode.name) sourceNode = $prevNode.name;
} catch (e) {
  // Fall through to the severity-based default below.
}

const str = (v) => (v === null || v === undefined) ? '' : String(v);
const riskLevel = str(deal.riskLevel);
const slackChannel = CHANNEL_BY_NODE[sourceNode] ||
  ((riskLevel === 'CRITICAL' || riskLevel === 'HIGH') ? '#revops-risk' : '#workflow-error');

const score = Number(deal.riskScore);
const lastAlertedAt = new Date().toISOString();

return {
  json: {
    dealId,
    dealName: str(deal.dealName),
    ownerId: str(deal.ownerId),
    riskLevel,
    riskScore: Number.isFinite(score) ? score : 0,
    issueFingerprint: str(deal.issueFingerprint),
    alertReason: str(deal.alertReason),
    actionSource: str(deal.actionSource),
    slackChannel,
    // Set by Decide Action Per Deal and never recalculated here.
    firstAlertedAt: str(deal.firstAlertedAt) || lastAlertedAt,
    lastAlertedAt,
    lastSeenAt: lastAlertedAt
  }
};

// Single error collector for the whole workflow.
// Turns many failed items into one Slack message that names the affected deals,
// instead of one message per failed item which would trip Slack's rate limit.
const items = $input.all();

let source = 'Unknown node';
try {
  if (typeof $prevNode !== 'undefined' && $prevNode && $prevNode.name) source = $prevNode.name;
} catch (e) {
  // Fall through to the default above.
}

const MAX_LINES = 20;
const MAX_DETAIL_CHARS = 160;
const lines = [];
const affected = [];

// Node errors arrive as plain objects rather than Error instances, so the
// readable text can sit under any of several keys depending on which node
// failed. Read them in order of usefulness and prefix with the error type.
const readError = (e, depth = 0) => {
  if (e === null || e === undefined || depth > 3) return null;
  if (typeof e === 'string') return e.trim() || null;
  if (typeof e !== 'object') return String(e);

  let detail = null;
  if (typeof e.message === 'string' && e.message.trim()) detail = e.message.trim();
  else if (typeof e.description === 'string' && e.description.trim()) detail = e.description.trim();
  else if (Array.isArray(e.messages) && e.messages.length) detail = String(e.messages[0]).trim();
  else if (e.cause) detail = readError(e.cause, depth + 1);

  const label = typeof e.name === 'string' && e.name ? e.name : null;
  if (detail && label) return label + ': ' + detail;
  return detail || label;
};

for (const item of items) {
  const json = (item && item.json) || {};
  const err = json.error || null;
  const rawId = json.dealId !== undefined && json.dealId !== null ? json.dealId : json.deal_id;
  const id = rawId === undefined || rawId === null || rawId === '' ? null : String(rawId);
  if (id) affected.push(id);

  let msg;
  if (err) {
    msg = readError(err) || 'Node error with no readable message';
  } else if (json.route) {
    msg = 'Item reached the error sink with an unexpected route "' + json.route + '"';
  } else {
    msg = 'Unknown error';
  }

  // Database errors can carry a very long detail line, and Slack has a hard
  // message size limit that applies to the whole grouped message.
  if (msg.length > MAX_DETAIL_CHARS) msg = msg.slice(0, MAX_DETAIL_CHARS - 1) + '…';

  if (lines.length < MAX_LINES) lines.push(id ? '- ' + id + ': ' + msg : '- ' + msg);
}
if (items.length > MAX_LINES) lines.push('- ...and ' + (items.length - MAX_LINES) + ' more');

return [{
  json: {
    failedNode: source,
    failureCount: items.length,
    errorMessage: lines.length ? lines.join('\n') : 'No error detail available',
    affectedDealIds: affected,
    occurredAt: new Date().toISOString(),
    executionId: $execution.id
  }
}];
